test('RATES contains EUR, USD, GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert returns ok with converted amount for EUR', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert returns ok with converted amount for USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  // 10000 EUR cents * 1.085 = 10850 USD cents
  assert.equal(result.value, 10850);
});

test('convert returns ok with converted amount for GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  // 10000 EUR cents * 0.8425 = 8425 GBP cents
  assert.equal(result.value, 8425);
});

test('convert handles fractional results with rounding', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  // 100 * 1.085 = 108.5 -> 108 or 109 (banker's rounding)
  assert.equal(result.value, 108);
});

test('convert handles small amounts', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  // 1 * 1.085 = 1.085 -> 1 (banker's rounding)
  assert.equal(result.value, 1);
});

test('convert returns UNKNOWN_CURRENCY for invalid currency', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert returns UNKNOWN_CURRENCY for missing currency', () => {
  const result = convert(10000, 'XXX');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('formatMoney formats EUR with € sign', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney formats USD with $ sign', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney formats GBP with £ sign', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney handles small amounts in all currencies', () => {
  assert.equal(formatMoney(5, 'EUR'), '€0.05');
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(5, 'GBP'), '£0.05');
});

test('formatMoney handles negative amounts', () => {
  assert.equal(formatMoney(-250, 'EUR'), '-€2.50');
  assert.equal(formatMoney(-250, 'USD'), '-$2.50');
  assert.equal(formatMoney(-250, 'GBP'), '-£2.50');
});

test('formatMoney handles large amounts with thousands separators', () => {
  assert.equal(formatMoney(100000000, 'EUR'), '€1,000,000.00');
  assert.equal(formatMoney(100000000, 'USD'), '$1,000,000.00');
  assert.equal(formatMoney(100000000, 'GBP'), '£1,000,000.00');
});

test('formatMoney with zero', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('convert and formatMoney work together', () => {
  const euros = 100000; // 1000 EUR
  const converted = convert(euros, 'USD');
  assert.equal(converted.ok, true);
  const formatted = formatMoney(converted.value, 'USD');
  // 1000 EUR * 1.085 = 1085 USD
  assert.equal(formatted, '$1,085.00');
});

test('convert preserves zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert all currencies from same EUR amount', () => {
  const eur = convert(100000, 'EUR');
  const usd = convert(100000, 'USD');
  const gbp = convert(100000, 'GBP');

  assert.equal(eur.ok, true);
  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);

  // USD should be more than EUR
  assert(usd.value > eur.value);
  // GBP should be less than EUR
  assert(gbp.value < eur.value);
});

test('formatMoney returns ? for unknown currency', () => {
  assert.equal(formatMoney(100, 'XYZ'), '?1.00');
});

